package mx.siabuc.helpdesk;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.assertThat;
class SupportPackageIntegrationIT extends ApiIntegrationSupport {
 @Autowired JdbcTemplate db;
 static Map<String,Object> payload(){var p=new LinkedHashMap<String,Object>();p.put("code",unique("PACK"));p.put("name","Soporte Biblioteca");p.put("description","Instalación y diagnóstico de SIABUC");p.put("amount",new BigDecimal("2500.50"));p.put("emailMinutes",120);p.put("remoteMinutes",60);p.put("expectedRevision",1);return p;}
 private Client staff(String role)throws Exception{String u=unique("package"+role);success(admin.post("/users",Map.of("username",u,"displayName",role,"password",PASSWORD,"role",role,"active",true,"email","packages@example.test")));return login(u,PASSWORD);}
 @Test void billingCreatesRevisionsAndDeactivatesWithoutErasingVersions()throws Exception{var b=staff("BILLING");var p=payload();var first=success(b.post("/support-packages",p));long id=first.path("current").path("packageId").asLong();long version=first.path("current").path("id").asLong();p.put("amount",new BigDecimal("3500.75"));var next=success(b.put("/support-packages/"+id,p));assertThat(next.path("versions")).hasSize(2);assertThat(next.path("current").path("revision").asInt()).isEqualTo(2);assertThat(next.path("versions").get(1).path("id").asLong()).isEqualTo(version);assertThat(next.path("versions").get(1).path("amount").decimalValue()).isEqualByComparingTo("2500.50");assertStatus(b.put("/support-packages/"+id,p),409);assertThat(success(b.post("/support-packages/"+id+"/active",Map.of("active",false))).path("current").path("active").asBoolean()).isFalse();assertThat(success(b.get("/support-packages/"+id)).path("versions")).hasSize(2);}
 @Test void invalidMoneyMinutesCodeAndClientOrTechnicianAreDenied()throws Exception{long institution=institution(0,0);var user=institutionUser(institution);var tech=staff("TECH");for(Client c:List.of(user,tech)){assertStatus(c.get("/support-packages"),403);assertStatus(c.post("/support-packages",payload()),403);assertStatus(c.get("/installments"),403);assertStatus(c.post("/installments/scan",Map.of()),403);}var p=payload();for(String amount:List.of("0","-1","10.001","1000000000")){p.put("amount",new BigDecimal(amount));assertStatus(admin.post("/support-packages",p),400);}p.put("amount",BigDecimal.ONE);p.put("emailMinutes",1.5);assertStatus(admin.post("/support-packages",p),400);p.put("emailMinutes",0);p.put("remoteMinutes",0);assertStatus(admin.post("/support-packages",p),400);p.put("remoteMinutes",1);p.put("code","<bad>");assertStatus(admin.post("/support-packages",p),400);assertStatus(admin.raw("POST","/support-packages",payload(),false),403);}
 @Test void quoteUsesServerVersionAndCatalogChangesDoNotRewriteIt()throws Exception{long institution=institution(15,30);var p=payload();var packageData=success(admin.post("/support-packages",p));long id=packageData.path("current").path("packageId").asLong(),version=packageData.path("current").path("id").asLong();var q=QuoteIntegrationIT.quotePayload(institution,null);q.put("packageVersionId",version);q.put("description",p.get("description"));q.put("agreedAmount",p.get("amount"));long quote=success(admin.post("/quotes",q)).path("quote").path("id").asLong();p.put("amount",new BigDecimal("9999.99"));success(admin.put("/support-packages/"+id,p));var retained=success(admin.get("/quotes/"+quote));assertThat(retained.path("packageSnapshot").path("amount").decimalValue()).isEqualByComparingTo("2500.50");assertThat(retained.path("quote").path("agreedAmount").decimalValue()).isEqualByComparingTo("2500.50");q.put("folio",unique("NEW"));assertStatus(admin.post("/quotes",q),409);q.put("folio",retained.path("quote").path("folio").asText());success(admin.put("/quotes/"+quote,q));assertBalance(institution,0,15,0,30);assertThat(db.queryForObject("SELECT COUNT(*) FROM payments WHERE institution_id=?",Long.class,institution)).isZero();}
 @Test void explicitOverridesPreserveSnapshotAndIssueFreezesNegotiatedTerms()throws Exception{long institution=institution(0,0);var p=payload();var packageData=success(admin.post("/support-packages",p));long version=packageData.path("current").path("id").asLong();var q=QuoteIntegrationIT.quotePayload(institution,null);q.put("packageVersionId",version);assertStatus(admin.post("/quotes",q),400);q.put("packageOverrideReason","Descuento autorizado y alcance específico para biblioteca");var saved=success(admin.post("/quotes",q));long id=saved.path("quote").path("id").asLong();assertThat(saved.path("packageOverrideReason").asText()).contains("Descuento autorizado");assertThat(saved.path("packageSnapshot").path("amount").decimalValue()).isEqualByComparingTo("2500.50");assertThat(saved.path("quote").path("agreedAmount").decimalValue()).isEqualByComparingTo("1234.56");success(admin.post("/quotes/"+id+"/send",Map.of("evidence","Entregada al contacto")));assertStatus(admin.put("/quotes/"+id,q),409);success(admin.post("/quotes/"+id+"/decision",QuoteIntegrationIT.decision("ACCEPTED",QuoteIntegrationIT.today())));var converted=success(admin.post("/quotes/"+id+"/convert",Map.of("policyFolio",unique("POLPKG"))));var policy=success(admin.get("/policies/"+converted.path("quote").path("convertedPolicyId").asLong()));assertThat(policy.path("policy").path("agreedAmount").decimalValue()).isEqualByComparingTo("1234.56");assertBalance(institution,0,0,0,0);}
 @Test void inactivePackagesCannotStartNewQuotesButHistoricalDraftRemainsEditable()throws Exception{long institution=institution(0,0);var p=payload();var d=success(admin.post("/support-packages",p));long packageId=d.path("current").path("packageId").asLong(),version=d.path("current").path("id").asLong();var q=QuoteIntegrationIT.quotePayload(institution,null);q.put("description",p.get("description"));q.put("agreedAmount",p.get("amount"));q.put("packageVersionId",version);long quote=success(admin.post("/quotes",q)).path("quote").path("id").asLong();success(admin.post("/support-packages/"+packageId+"/active",Map.of("active",false)));success(admin.put("/quotes/"+quote,q));q.put("folio",unique("INACTIVE"));assertStatus(admin.post("/quotes",q),409);assertThat(success(admin.get("/quotes/"+quote)).path("packageSnapshot").path("revision").asInt()).isEqualTo(1);}
}
